// NOVEL (hand-authored) — not generated by CLI Printing Press.

package cli

import (
	"testing"
	"time"
)

func TestPlanForwardWindows_SplitsAtTheCapAndNeverOvershoots(t *testing.T) {
	from := mustParseCivilDay("2026-01-01")
	to := mustParseCivilDay("2026-03-01") // 60 days inclusive

	windows := planForwardWindows(from, to, 28)
	if len(windows) != 3 {
		t.Fatalf("windows = %d, want 3 (28+28+4)", len(windows))
	}
	if got := windows[0].String(); got != "2026-01-01..2026-01-28" {
		t.Fatalf("first window = %s", got)
	}
	if got := windows[1].String(); got != "2026-01-29..2026-02-25" {
		t.Fatalf("second window = %s", got)
	}
	if got := windows[2].String(); got != "2026-02-26..2026-03-01" {
		t.Fatalf("last window = %s, want it to stop at `to` rather than overshoot", got)
	}
	for i, w := range windows {
		if w.days() > 28 {
			t.Fatalf("window %d covers %d days; Garmin rejects a range over 28 with HTTP 400", i, w.days())
		}
	}
	// Every day in the range is covered exactly once.
	covered := map[string]int{}
	for _, w := range windows {
		for d := w.start; !d.after(w.end); d = d.addDays(1) {
			covered[d.String()]++
		}
	}
	if len(covered) != 60 {
		t.Fatalf("covered %d distinct days, want 60", len(covered))
	}
	for day, n := range covered {
		if n != 1 {
			t.Fatalf("day %s covered %d times, want exactly 1", day, n)
		}
	}
}

func TestPlanForwardWindows_EmptyRangeCostsNothing(t *testing.T) {
	day := mustParseCivilDay("2026-05-04")
	if w := planForwardWindows(day.addDays(1), day, 28); len(w) != 0 {
		t.Fatalf("a caught-up series planned %d windows; it must plan none", len(w))
	}
	if w := planForwardWindows(day, day, 28); len(w) != 1 || w[0].days() != 1 {
		t.Fatalf("a single-day range = %v, want one 1-day window", w)
	}
}

func TestCivilDayArithmetic_CrossesMonthYearAndLeapBoundaries(t *testing.T) {
	cases := []struct {
		from, want string
		n          int
	}{
		{"2026-01-31", "2026-02-01", 1},
		{"2026-12-31", "2027-01-01", 1},
		{"2028-02-28", "2028-02-29", 1}, // 2028 is a leap year
		{"2027-02-28", "2027-03-01", 1}, // 2027 is not
		{"2026-03-01", "2026-02-28", -1},
		{"2026-01-01", "2025-12-03", -29},
	}
	for _, c := range cases {
		if got := mustParseCivilDay(c.from).addDays(c.n).String(); got != c.want {
			t.Fatalf("%s + %d days = %s, want %s", c.from, c.n, got, c.want)
		}
	}
}

// A daylight-saving transition must not move a calendar boundary. Both US
// transitions are exercised: the spring-forward day is 23 hours long in local
// time and the fall-back day is 25, and a naive 24-hour arithmetic would skip
// or repeat a date across them.
func TestCivilDayArithmetic_IsUnaffectedByDaylightSaving(t *testing.T) {
	la, err := time.LoadLocation("America/Los_Angeles")
	if err != nil {
		t.Skipf("tzdata unavailable: %v", err)
	}
	for _, c := range []struct{ label, start, want string }{
		{"spring forward 2026-03-08", "2026-03-07", "2026-03-08"},
		{"fall back 2026-11-01", "2026-10-31", "2026-11-01"},
	} {
		if got := mustParseCivilDay(c.start).addDays(1).String(); got != c.want {
			t.Fatalf("%s: %s + 1 day = %s, want %s", c.label, c.start, got, c.want)
		}
	}

	// A window spanning the spring-forward day covers 28 distinct dates,
	// not 27, even though local elapsed time is 27 days and 23 hours.
	windows := planForwardWindows(mustParseCivilDay("2026-02-25"), mustParseCivilDay("2026-03-24"), 28)
	if len(windows) != 1 || windows[0].days() != 28 {
		t.Fatalf("windows across the DST boundary = %v", windows)
	}

	// today() reads the caller's zone, because Garmin's calendarDate is the
	// account holder's local date. 2026-03-08 07:30 UTC is still 2026-03-07
	// in Los Angeles.
	instant := time.Date(2026, 3, 8, 7, 30, 0, 0, time.UTC)
	now := func() time.Time { return instant }
	if got := today(now, la).String(); got != "2026-03-07" {
		t.Fatalf("today in Los Angeles = %s, want 2026-03-07", got)
	}
	if got := today(now, time.UTC).String(); got != "2026-03-08" {
		t.Fatalf("today in UTC = %s, want 2026-03-08", got)
	}
}

// Today's row is still accruing, so it can be stored but never bookmarked as
// complete. Yesterday is the newest day a walk may call complete.
func TestCompleteDayCeiling_ExcludesToday(t *testing.T) {
	now := mustParseCivilDay("2026-09-08")
	if got := completeDayCeiling(now).String(); got != "2026-09-07" {
		t.Fatalf("complete-day ceiling = %s, want yesterday (2026-09-07)", got)
	}
	if got := minDay(now, completeDayCeiling(now)).String(); got != "2026-09-07" {
		t.Fatalf("clamping today against the ceiling = %s, want 2026-09-07", got)
	}
	// Month boundary: the ceiling on the first of a month is the last day
	// of the previous one.
	if got := completeDayCeiling(mustParseCivilDay("2026-03-01")).String(); got != "2026-02-28" {
		t.Fatalf("ceiling on 2026-03-01 = %s, want 2026-02-28", got)
	}
}

func TestParseCivilDay_RejectsNonDates(t *testing.T) {
	for _, bad := range []string{"", "2026-13-01", "not-a-date", "2026/09/08", "20260908"} {
		if _, err := parseCivilDay(bad); err == nil {
			t.Fatalf("parseCivilDay(%q) accepted a non-date", bad)
		}
	}
}
